    await expect(pg_vic.getByTestId("consolidated-settled-total")).toHaveText("1.00");
    await expect(pg_vic.getByTestId("consolidated-open-total")).toHaveText("4.00");
    await expect(pg_vic.getByTestId("consolidated-cut-total")).toHaveText("6.00");
    await expect(pg_vic.getByTestId("sheet-preview")).toHaveText("");
    await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("60.00");
